# Summarise setter records and getter callers from the stock probe.
# Do not edit this file after it has run.
import json
from collections import Counter
from pathlib import Path

rows = [json.loads(line) for line in Path('work/out/stock-probe-m1.jsonl').read_text(encoding='utf-8').splitlines() if line]
want = {
    'open-up', 'open-up-dial-main', 'open-up-dial-sub', 'open-up-ok', 'open-up-right',
    'row-0-ok', 'row-1-ok',
}
print('steps', len(rows))
for row in rows:
    if row.get('step') not in want and not row.get('sets'):
        continue
    if not row.get('sets') and row.get('step') not in want:
        continue
    sets = row.get('sets') or []
    if row.get('step') not in want and not sets:
        continue
    callers = Counter(g['caller'] for g in row.get('gets') or [])
    keys = Counter((g['key'], g['index']) for g in row.get('gets') or [])
    print('\n==', row.get('step'), 'sets', len(sets), 'diff', row.get('diff'))
    for s in sets:
        print('  set', s)
    print('  get callers', callers.most_common(6))
    print('  get keys', keys.most_common(12))
